function memorial_icon($name, $class = '', $title = '')
{
    static $paths = null;
    if ($paths === null) {
        $paths = memorial_icon_paths();
    }
    if (!isset($paths[$name])) {
        return '';
    }
    $label = $title ? ' role="img" aria-label="' . esc_attr($title) . '"' : ' aria-hidden="true" focusable="false"';
    return '<svg class="ic ic-' . esc_attr($name) . ($class ? ' ' . esc_attr($class) : '') . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"' . $label . '>' . $paths[$name] . '</svg>';
}
